function allPositive(nums) {
  return nums.every((n) => n > 0);
}

function anyNegative(nums) {
  return nums.some((n) => n < 0);
}

function allPositive(nums) {
  for (const n of nums) {
    if (n <= 0) return false;
  }
  return true;
}

function anyNegative(nums) {
  for (const n of nums) {
    if (n < 0) return true;
  }
  return false;
}
